import {PACKING_CASES} from './parcel-packing-content.mjs';
import * as core from './parcel-packing-core.mjs';
import {packingBagArt,packingLooseArt,packingDispatchArt} from './parcel-packing-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pages=[['pack','Pack'],['read','Read'],['purpose','Purpose'],['keep','Keep']];
const btn=(attrs,label,{disabled=false,on=null,primary=false,className=''}={})=>`<button type="button" class="${className} ${primary?'primary':'secondary'}${on?' selected':''}" ${attrs}${disabled?' disabled':''}${on===null?'':` aria-pressed="${on}"`}>${label}</button>`;
const options=(value)=>[['','Choose a unit'],['full bags','full bags'],['loose envelopes','loose envelopes'],['loaded trips','loaded trips']].map(([id,label])=>`<option value="${esc(id)}"${(value??'')===id?' selected':''}>${label}</option>`).join('');
const purposeName=p=>p==='kits'?'Full welcome kits':'Carry every envelope';
function counts(c,bags){const packed=bags.reduce((a,b)=>a+b,0);return {packed,loose:c.total-packed,fullBags:bags.filter(n=>n===c.capacity).length,partialBags:bags.filter(n=>n>0&&n<c.capacity).length,loadedBags:bags.filter(n=>n>0).length};}
export function parcelPackingEntry(){return '<aside class="pp-entry"><div><h2>Willow’s packing table</h2><p>Make full welcome kits, or carry every seed envelope. Does the purpose change the answer?</p></div><a class="secondary" href="#post/packing">Try the packing table</a></aside>';}
export function renderParcelPacking(state){
 const facts=[];
 // Reporting a relationship lives beside its visible words; hidden records are never scanned.
 const group=(source,bags,label='Complete equal groups')=>{const m=counts(source,bags),n=m.fullBags;if(n>=1&&n<=12&&source.capacity>=1&&source.capacity<=12)facts.push([n,source.capacity]);return `<section class="pp-group"><strong>${esc(label)}</strong><p>${n?`${n} full ${n===1?'bag':'bags'} × ${source.capacity} envelopes in each = ${n*source.capacity} envelopes in complete groups.`:'No full bags yet.'}</p>${n?`<p class="tiny">${Array(n).fill(source.capacity).join(' + ')} = ${n*source.capacity} envelopes in full bags.</p>`:''}<p class="tiny">${m.partialBags} partly filled ${m.partialBags===1?'bag':'bags'} · ${m.loose} loose envelopes. Partial bags stay separate.</p></section>`;};
 const feedback=(v,kind)=>{const check=v.latestChecks?.[kind];if(!check)return `<div id="pp-feedback-${kind}" class="pp-feedback" role="status" tabindex="-1" hidden></div>`;const a=check.assessment||{},d=check.input||{},bags=d.bags||check.bags;const response=d.response||d.reading||d.answer;return `<section id="pp-feedback-${kind}" class="pp-feedback" role="status" tabindex="-1"><strong>${v.currentFeedback?.[kind]?'This check':'An earlier check'}</strong><p>${esc(checkText(kind,a,response))}</p>${bags?group(check.source,bags,'The table at this check'):''}</section>`;};
 const snapshot=(s,title,earlier,id)=>{if(!s)return '';const d=s.input||s.draft||s;return `<section class="pp-snapshot" id="${id}" tabindex="-1"><h3>${title}${earlier?' · earlier work':''}</h3><p>${esc(s.source?.title)} · ${purposeName(d.purpose)}</p>${group(s.source,d.bags,'The packing kept here')}<p>${s.assessment?.ready?'This plan was ready for its chosen purpose.':'A plan to return to and revise.'}</p><p class="tiny">Later changes leave this saved plan as it was.</p></section>`;};
 const r=core.packingState(state);
 if(!r)return {html:'<section class="pp-workspace" data-pp-root><h1 id="pp-title" tabindex="-1">Your earlier packing record is kept</h1><p>This format cannot be opened here. Its exact record remains available in notes downloads.</p><button type="button" class="secondary" data-pp-recover>Keep that record and start fresh</button><p><a href="#post">Return to the Post Office</a></p></section>',facts};
 const header='<header><a class="back" href="#post">← Back to my Post Office parcel</a><h1>Willow’s packing table</h1><p>The same seed envelopes. Two different jobs.</p></header>';
 if(r.page==='choose'||!r.currentCase)return {html:`<div class="pp-workspace" data-pp-root>${header}<h2 id="pp-title" tabindex="-1">Which seed request shall we pack?</h2><div class="pp-chooser">${PACKING_CASES.map(c=>btn(`data-pp-case="${c.id}"`,`<strong>${esc(c.title)}</strong><span>${c.total} envelopes · each bag holds ${c.capacity}</span><small>${r.cases[c.id]?'Return to your familiar draft':'Try either purpose'}</small>`)).join('')}</div><p>Every request stays open, including the exact fit.</p></div>`,facts};
 const v=core.packingView(state),w=v.work,c=v.case,m=v.model;
 const mat=()=>`<div class="pp-mat" role="group" aria-label="Eight numbered bag spaces">${w.bags.map((n,i)=>btn(`data-pp-bag="${i}"`,`<strong>Bag ${i+1}</strong>${packingBagArt(n,c.capacity,{label:`Bag ${i+1}`})}`,{on:w.selectedBag===i,className:'pp-bag-button'})).join('')}</div>`;
 const model=()=>`<section class="pp-model" aria-label="Current packing table">${r.page==='pack'?'':`<h3>Selected bag ${w.selectedBag+1}</h3><div class="pp-mini-model">${packingBagArt(w.bags[w.selectedBag],c.capacity,{label:`Selected bag ${w.selectedBag+1}`})}<p>${m.fullBags} full bags<br>${m.partialBags} partly filled bags<br>${m.loadedBags} nonempty bags</p></div>`}<h3>Loose pile · ${m.loose} envelopes</h3>${packingLooseArt(m.loose)}${group(c,w.bags)}</section>`;
 const error=kind=>`<p class="pp-error" id="pp-error-${kind}" role="status" tabindex="-1"${w.inputError===kind?'':' hidden'}>Use a whole number from 0 to 100. Blank or other number forms stay as drafts.</p>`;
 const form=(kind,label,draft)=>`<form data-pp-form="${kind}" novalidate><h3>${label}</h3><div class="pp-fields"><label>My number<input id="pp-number-${kind}" data-pp-number="${kind}" type="text" inputmode="numeric" maxlength="24" autocomplete="off" value="${esc(draft.text)}" aria-describedby="pp-error-${kind}" aria-invalid="${w.inputError===kind}"></label><label>My unit<select data-pp-unit="${kind}" aria-describedby="pp-error-${kind}">${options(draft.unit)}</select></label></div>${error(kind)}<button class="secondary" type="submit">Check this ${kind.startsWith('read-')?'reading':'answer'}</button></form>${feedback(v,kind)}`;
 let task='';
 if(r.page==='pack')task=`<h2 id="pp-title" tabindex="-1">Put an envelope in a bag</h2><p>Choose any numbered bag. Dashed spaces show empty room.</p>${mat()}<p>Bag <strong>${w.selectedBag+1}</strong> is selected: ${w.bags[w.selectedBag]} of ${c.capacity} envelopes. ${m.loose} envelopes remain loose.</p><div class="pp-controls">${btn('data-pp-move="1"','+ Pack one envelope',{disabled:m.loose===0||w.bags[w.selectedBag]===c.capacity,primary:true})}${btn('data-pp-move="-1"','− Return one envelope',{disabled:w.bags[w.selectedBag]===0})}${btn('data-pp-return-bag','Empty this bag',{disabled:w.bags[w.selectedBag]===0})}</div>${btn('data-pp-counted-fill','Count and fill this bag together',{disabled:m.loose===0||w.bags[w.selectedBag]===c.capacity})}<p class="tiny">Requested counting help fills only the free places in this selected bag.</p><div class="pp-controls">${btn('data-pp-clear','Return every envelope to the loose pile',{disabled:m.packed===0})}${btn('data-pp-page="read"','Read my table')}</div>`;
 else if(r.page==='read')task=`<h2 id="pp-title" tabindex="-1">What is on this table now?</h2><p>Read the actual packing. A partly filled bag is separate from both full bags and loose envelopes.</p>${form('read-full','How many bags are completely full?',w.readings.full)}${form('read-loose','How many envelopes are still loose?',w.readings.loose)}<p class="tiny">A correct table reading stays correct even when the plan needs a change.</p>`;
 else if(r.page==='purpose')task=`<h2 id="pp-title" tabindex="-1">What job must this packing do?</h2>${purposes(w.purpose)}<p>${w.purpose==='kits'?`Make the greatest number of complete welcome kits. Each kit needs a full bag of ${c.capacity}; spare envelopes may wait loose.`:`Carry all ${c.total} envelopes in as few loaded trips as possible. One nonempty bag goes per outward trip; a partial bag may travel. Empty returns do not count.`}</p>${form(w.purpose,w.purpose==='kits'?'What is the greatest number of full kits?':'What is the fewest number of loaded trips?',w.answers[w.purpose])}<p>Both purposes keep their own answer draft. Changing purpose keeps this same actual table.</p>`;
 else task=`<h2 id="pp-title" tabindex="-1">Keep this plan, or seal it?</h2><p>Chosen job: <strong>${purposeName(w.purpose)}</strong>.</p><ul class="pp-summary"><li>${readyText(v)}</li><li>Unfinished plans can be kept. You can return and change every bag.</li></ul><div class="pp-controls">${btn('data-pp-keep',w.kept?'Replace kept plan':'Keep this plan',{primary:true})}${btn('data-pp-seal','Seal this plan',{primary:true,disabled:!v.assessment.ready||!!(w.sealed&&!v.sealedEarlier)})}</div>${snapshot(w.kept,'Your kept plan',v.keptEarlier,'pp-kept')}${w.sealed?`<section id="pp-sealed" class="pp-snapshot" tabindex="-1">${packingDispatchArt((w.sealed.input||w.sealed).purpose)}<h3>Your sealed plan is ready for Willow</h3><p>${(w.sealed.input||w.sealed).purpose==='kits'?'Complete welcome kits can go; spare envelopes wait for a later kit.':'Every envelope has a place for its outward journey.'}</p>${snapshot(w.sealed,'The sealed packing',v.sealedEarlier,'pp-sealed-packing')}<p>You can try the other job, or choose another request.</p></section>`:''}`;
 const help=()=>{let body='';const t=w.helpTopic;if(t==='group')body='<h3>Make equal groups</h3><p>Every full bag has the same number of envelopes: its capacity. Count the full bags separately from the envelopes inside them. A partly filled bag is not another complete kit.</p>';if(t==='partial')body='<h3>Partly filled is different from loose</h3><p>An envelope inside a partly filled bag is packed. It is not in the loose pile. A partial bag can make a loaded trip, but it cannot be a full welcome kit.</p>';if(t==='capacity')body=`<h3>How much fits?</h3><p>Each bag here holds at most ${c.capacity} seed envelopes. Dashed spaces show spare room, not spare envelopes. An empty bag does not count as a loaded trip.</p>`;if(t==='meaning')body='<h3>The purpose changes what we count</h3><p>For welcome kits, count only complete bags and leave spares loose. For delivery, every envelope must travel; count nonempty bags and seek the fewest trips. If every envelope already fits into full bags, no extra trip is needed.</p>';if(t==='example')body=example(v,group);return `<aside class="pp-ideas"><h2>Ideas to try together</h2><div class="pp-help-nav">${[['group','Equal groups'],['partial','Partial or loose?'],['capacity','Bag capacity'],['meaning','Two purposes'],['example','A separate worked example']].map(([id,label])=>btn(`data-pp-help="${id}"`,label,{on:t===id})).join('')}</div>${t?`<section id="pp-help" class="pp-help" tabindex="-1"><p class="pp-support">Supplied support · your current packing stays as it was</p>${body}${btn('data-pp-help=""','Close ideas')}</section>`:''}<div class="pp-controls">${btn('data-pp-together','We’re working together',{on:!!w.support.together})}<span data-pp-audio>${hearButton(`${c.total} seed envelopes. Each bag holds ${c.capacity}. ${purposeName(w.purpose)}. You can pack and unpack one envelope at a time.`,'Hear this request')}</span></div><p><strong>Prepare this request together</strong> replaces your editable bags and chosen-purpose answer. Your kept and sealed plans stay as they were. It does not seal.</p>${btn('data-pp-ready','Replace my packing with a ready example together')}</aside>`;};
 const html=`<div class="pp-workspace pp-page-${r.page}" data-pp-root>${header}<section class="pp-request"><div><strong>${esc(c.title)}</strong><p>${c.total} seed envelopes · capacity ${c.capacity} envelopes per bag</p></div><div><strong>${purposeName(w.purpose)}</strong><p>One nonempty bag per loaded outward trip.</p></div></section><nav class="pp-pages" aria-label="Open packing task pages">${pages.map(([id,label])=>btn(`data-pp-page="${id}"`,label,{on:r.page===id})).join('')}</nav><div class="pp-layout"><section class="pp-turn">${task}<p id="pp-status" class="pp-status" tabindex="-1" role="status"></p></section>${model()}</div>${help()}<div class="pp-footer">${btn('data-pp-page="choose"','Choose another seed request')}${r.page!=='keep'?btn('data-pp-keep','Keep this unfinished plan'):''}<a href="#notes">Grown-up notes</a><a href="#post">Return to my Post Office parcel</a></div></div>`;
 return {html,facts:[...new Map(facts.map(pair=>[pair.join(','),pair])).values()]};
}
function purposes(p){return `<div class="pp-controls" role="group" aria-label="Choose the packing purpose">${btn('data-pp-purpose="kits"','Make full welcome kits',{on:p==='kits'})}${btn('data-pp-purpose="all"','Carry every envelope',{on:p==='all'})}</div>`;}
function readyText(v){return v.assessment.ready?'The packing and labelled answer fit this job. You can seal it.':v.work.purpose==='kits'?'For this job, make the greatest possible number of full bags, leave only the spares loose, and choose the full-bag answer and unit.':'For this job, pack every envelope in the fewest nonempty bags, then choose the loaded-trip answer and unit. Any arrangement that fits is welcome.';}
function checkText(kind,a){const reading=kind.startsWith('read-');let text=`${a.number} ${a.numberMatches?'matches':'differs from'} ${a.target} ${a.expectedUnit}. Your unit ${a.unitMatches?'matches':'needs a change'}.`;if(!reading)text+=` ${a.planReady?'The actual packing fits this purpose.':kind==='all'?`${a.carriesAll?'Every envelope is packed.':'Some envelopes are still loose.'} ${a.minimalTrips?'The nonempty-bag count is minimal.':'The nonempty-bag count is not the fewest loaded trips.'}`:'The actual packing still needs the greatest possible number of full bags, no partial bags, and the spares loose.'}`;return text;}

function example(v,group){const step=v.work.exampleStep??0,bags=step===0?[0,0,0,0,0,0,0,0]:step===1?[4,0,0,0,0,0,0,0]:step===2?[4,4,4,0,0,0,0,0]:[4,4,4,2,0,0,0,0],source={total:14,capacity:4};return `<h3>Separate example · 14 envelopes, capacity 4</h3><p>${['Start with fourteen loose envelopes. Each bag can hold four.','One complete bag has four envelopes. Ten envelopes are still loose.','Three full kits hold twelve envelopes. Two spare envelopes can wait loose.','For delivery, put those two envelopes in another bag. Four loaded trips carry all fourteen.'][step]}</p><div class="pp-mini-model">${bags.filter(n=>n>0).map((n,i)=>packingBagArt(n,4,{label:`Example bag ${i+1}`})).join('')}</div>${packingLooseArt(14-bags.reduce((a,b)=>a+b,0))}${group(source,bags,'Complete groups in this supplied example')}<div class="pp-controls">${btn('data-pp-example="-1"','Previous example step',{disabled:step===0})}${btn('data-pp-example="1"','Next example step',{disabled:step===3})}</div><p class="tiny">Your real request is unchanged.</p>`;}
export function parcelPackingNotes(state){if(!Object.hasOwn(state,'parcelPacking'))return '';return `<details class="panel" data-pp-notes><summary>Willow packing table: actual readings and chosen purposes</summary><p>Supplied pictured practice. Full-group counts, loose envelopes, partial bags and loaded trips stay separate. Checks retain frozen responses, model and support before feedback. Keeping or sealing is not independent attainment, a Post Office delivery or Bramble progress.</p><pre class="pp-note-pre">${esc(JSON.stringify(state.parcelPacking,null,2))}</pre></details>`;}

export function bindParcelPacking(state,ctx){
 if(!document.querySelector('[data-pp-root]'))return;
 const focus=selector=>{const el=document.querySelector(selector);if(el&&!el.disabled){ctx.focus?.(selector);return;}const group=el?.closest('.pp-controls,.pp-help,.pp-turn');if(group){const next=group.querySelector('button:not(:disabled)');if(next){next.focus();return;}group.tabIndex=-1;group.focus();return;}ctx.focus?.('#pp-status');};
 const refresh=(target='#pp-title')=>{ctx.save();ctx.render();focus(target);};
 const status=text=>{const el=document.querySelector('#pp-status');if(el){el.textContent=text;focus('#pp-status');}};
 const act=(fn,target='#pp-title')=>{const result=fn();if(result!==false&&result!==null)refresh(target);else status('That move is not available. Your packing is still here.');return result;};
 const all=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 all('[data-pp-case]',b=>act(()=>core.choosePackingCase(state,b.dataset.ppCase)));
 all('[data-pp-page]',b=>act(()=>core.setPackingPage(state,b.dataset.ppPage)));
 all('[data-pp-recover]',()=>act(()=>core.recoverPacking(state)));
 all('[data-pp-bag]',b=>act(()=>core.selectPackingBag(state,Number(b.dataset.ppBag)),`[data-pp-bag="${b.dataset.ppBag}"]`));
 all('[data-pp-move]',b=>act(()=>core.movePackingEnvelope(state,Number(b.dataset.ppMove)),`[data-pp-move="${b.dataset.ppMove}"]`));
 all('[data-pp-return-bag]',()=>act(()=>core.returnPackingBag(state),'[data-pp-return-bag]'));
 all('[data-pp-clear]',()=>act(()=>core.clearPackingTable(state),'[data-pp-clear]'));
 all('[data-pp-counted-fill]',()=>{const before=core.packingView(state).model.packed;if(act(()=>core.fillPackingBagTogether(state),'[data-pp-counted-fill]')!==false){const v=core.packingView(state);status(`Counted together: moved ${v.model.packed-before} envelopes into bag ${v.work.selectedBag+1}. It now holds ${v.work.bags[v.work.selectedBag]} of ${v.case.capacity}.`);}});
 all('[data-pp-purpose]',b=>act(()=>core.setPackingPurpose(state,b.dataset.ppPurpose),`[data-pp-purpose="${b.dataset.ppPurpose}"]`));
 document.querySelectorAll('[data-pp-form]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const kind=form.dataset.ppForm;const result=core.checkPacking(state,kind);if(result!==false)refresh(result.valid===false?`#pp-error-${kind}`:`#pp-feedback-${kind}`);}));
 all('[data-pp-keep]',()=>act(()=>{const result=core.keepPacking(state);if(result!==false)core.setPackingPage(state,'keep');return result;},'#pp-kept'));
 all('[data-pp-seal]',()=>act(()=>core.sealPacking(state),'#pp-sealed'));
 all('[data-pp-help]',b=>act(()=>core.setPackingHelp(state,b.dataset.ppHelp||null),b.dataset.ppHelp?'#pp-help':'[data-pp-help="group"]'));
 all('[data-pp-example]',b=>act(()=>core.stepPackingExample(state,Number(b.dataset.ppExample)),`[data-pp-example="${b.dataset.ppExample}"]`));
 all('[data-pp-together]',()=>act(()=>core.usePackingSupport(state,'together'),'[data-pp-together]'));
 all('[data-pp-ready]',()=>{if(act(()=>core.preparePackingTogether(state),'#pp-status')!==false)status('Prepared together: the editable packing and chosen-purpose answer have been replaced. Your kept and sealed plans remain. Choose Keep to review and explicitly seal.');});
 document.querySelectorAll('[data-pp-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{core.usePackingSupport(state,'narration');ctx.save();}));
 // Save each raw edit without replacing its input node or moving its caret.
 const saved=(changed,kind)=>{if(!changed)return;ctx.save();document.querySelectorAll('.pp-error').forEach(el=>{el.hidden=true;});document.querySelectorAll('[aria-invalid]').forEach(el=>el.setAttribute('aria-invalid','false'));const feedback=document.getElementById(`pp-feedback-${kind}`);if(feedback)feedback.hidden=true;const el=document.querySelector('#pp-status');if(el)el.textContent='Draft saved.';};
 document.querySelectorAll('[data-pp-number]').forEach(el=>el.addEventListener('input',e=>{const kind=el.dataset.ppNumber;const changed=kind.startsWith('read-')?core.setPackingReading(state,kind.slice(5),e.target.value):core.setPackingAnswer(state,kind,e.target.value);saved(changed,kind);}));
 document.querySelectorAll('[data-pp-unit]').forEach(el=>el.addEventListener('change',e=>{const kind=el.dataset.ppUnit,value=e.target.value||null;const changed=kind.startsWith('read-')?core.setPackingReadingUnit(state,kind.slice(5),value):core.setPackingAnswerUnit(state,kind,value);saved(changed,kind);}));
}
